// Cross-language golden vectors generated by the ACTUAL Rust chain code
// (xriq-core + xriq-crypto) for a fixed seed [5u8;32] and a fixed transfer.
// Proves the TS wallet reproduces the chain's signing hash, signature, and tx hash
// byte-for-byte. Regenerate with the xriqvec Rust helper if the protocol changes.
import {
  keypairFromSeed,
  signTransfer,
  transactionSigningHash,
  transactionHash,
  hex,
  type XriqTransaction,
} from '../src/core/xriq';

const RUST = {
  pubkey: '6e7a1cdd29b0b78fd13af4c5598feff4ef2a97166e3ca6f2e4fbfccd80505bf1',
  address: 'xriqdev1efa2325e4dd056957e1e07d76620cb792413c975',
  signingHash: '8b7f0d14940ccffc272c08e314f24906d35c5cda64e649c72a703926b4e9262c',
  signature:
    'dea9890be0329e40543cec114783f28951fa0f354b82db7b59e610d78d1d976f82ea8447dd04e6e8e33e87fa2c4e5f9cff2580b474f3edb16699cb40563e0403',
  txHash: '2bea79e72e7f481cd3e0b79cc0d7951fa1e9e9367d0b8e0ed3fbac7f1fe14c09',
};

let fail = 0;
function eq(name: string, got: string, want: string) {
  if (got === want) console.log(`  ok   ${name}`);
  else {
    fail++;
    console.error(`  FAIL ${name}\n    got  ${got}\n    want ${want}`);
  }
}

const seed = new Uint8Array(32).fill(5);
const kp = keypairFromSeed(seed);
eq('public key', hex.toHex(kp.publicKey), RUST.pubkey);
eq('address', kp.address, RUST.address);

const tx: XriqTransaction = {
  version: 1,
  chainId: 'xriq-devnet',
  from: RUST.address,
  to: 'xriqdev1397e043c1939ff954726c0f3657a7a5093b33b89',
  amountBaseUnits: 25n,
  feeBaseUnits: 2n,
  nonce: 7n,
  memoHash: null,
  expiresAtHeight: null,
  publicKey: kp.publicKey,
};
eq('transaction signing hash', hex.toHex(transactionSigningHash(tx)), RUST.signingHash);
const signed = signTransfer(tx, seed);
eq('ed25519 signature', hex.toHex(signed.signature), RUST.signature);
eq('transaction hash', hex.toHex(transactionHash(tx, signed.signature)), RUST.txHash);

console.log(fail === 0 ? '\nALL RUST VECTORS MATCH ✓' : `\n${fail} MISMATCH(ES)`);
if (fail > 0) process.exit(1);
